<?php $eyebrow=$event['year'].' ARŞİVİ'; $heading=$event['title']; $summary=$event['description']; $heroImage=$event['hero_image']; require BASE_PATH . '/templates/page-hero.php'; ?>
<section class="article-layout section-pad"><div class="container"><div class="archive-stats"><div><small>Tarih</small><b><?= e(format_date_tr($event['start_date'])) ?> — <?= e(format_date_tr($event['end_date'])) ?></b></div><div><small>Yer</small><b><?= e($event['location']) ?></b></div><div><small>Program</small><b><?= count($sessions) ?> oturum</b></div></div><?php if ($sessions): ?><div class="session-list full"><?php foreach ($sessions as $session): ?><article class="session-row"><time><?= e(substr($session['start_time'],0,5)) ?></time><span class="session-type"><?= e($session['type']) ?></span><div><h3><?= e($session['title']) ?></h3><p><?= e($session['participants']) ?></p></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h2>Arşiv içeriği hazırlanıyor.</h2><p>Program, konuşmacı ve video kayıtlarını yönetim panelinden bu yıla ekleyebilirsiniz.</p></div><?php endif; ?><?php if ($videos): ?><div class="archive-video-head"><h2><?= e($event['year']) ?> video arşivi</h2></div><div class="video-grid"><?php foreach ($videos as $video): ?><article class="video-card"><div><iframe loading="lazy" src="<?= e($video['youtube_url']) ?>" title="<?= e($video['title']) ?>" allowfullscreen></iframe></div><h3><?= e($video['title']) ?></h3></article><?php endforeach; ?></div><?php endif; ?></div></section>
